import {normalizeState,defaults,readState} from './engine.js';
export const htmlEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mergeCourses(a,b){const out={...a};for(const[k,v]of Object.entries(b||{})){const old=out[k];out[k]=old?{...old,...v,correct:[...new Set([...old.correct,...v.correct])],hints:[...new Set([...old.hints,...v.hints])],stage:Math.max(old.stage,v.stage),project:{...old.project,...v.project}}:v}return out}
export function mergeProgress(remote,local){const a=normalizeState(remote),b=normalizeState(local);const attempts={...a.attempts};for(const[k,v]of Object.entries(b.attempts))if(!attempts[k]||v.tries>=attempts[k].tries)attempts[k]=v;return normalizeState({...a,...b,age:b.age||a.age,completed:{...a.completed,...b.completed},course:mergeCourses(a.course,b.course),focus:{...b.focus,sessions:[...new Map([...a.focus.sessions,...b.focus.sessions].map(x=>[x.date,x])).values()].slice(-100)},attempts,notes:{...a.notes,...b.notes},bookmarks:[...new Set([...a.bookmarks,...b.bookmarks])],visits:[...new Set([...a.visits,...b.visits])]});}
export function accountControls(user,status=''){return user?`<details class="account-menu"><summary><span class="avatar">${htmlEscape((user.full_name||user.username).slice(0,2).toUpperCase())}</span><span>${htmlEscape(user.full_name||user.username)}<small>@${htmlEscape(user.username)}</small></span><span aria-hidden="true">⌄</span></summary><div class="account-dropdown"><span class="micro">${htmlEscape(status)}</span><button data-page="profile">Profile Settings</button><button data-account="logout">Log Out</button></div></details>`:`<div class="auth-buttons"><button class="btn secondary small" data-page="login">Log In</button><button class="btn small" data-page="signup">Sign Up</button></div>`;}
export function createAccounts({getState,onState,onChange,notify,navigate,resetPrivateUI}){let user=null,configured=null,status='Guest · Saved on this device',revision=0,dirty=false,busy=false,error='',notice='',pending=null,timer=null,flushing=null,generation=0,canSync=false,sequence=0;const cacheKey=id=>'nexora-account:'+id;
 async function api(path,body,method=body===undefined?'GET':'POST'){let response;try{response=await fetch(path,{method,credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json','X-Nexora-Request':'1'},body:body===undefined?undefined:JSON.stringify(body)})}catch{throw Error('Cannot reach the server. Your local progress is preserved.')}let data;try{data=await response.json()}catch{throw Error('Account services are unavailable on this static deployment. Run the included Node server with Supabase configured.')}if(!response.ok){const e=Error(data.error||'Account request failed.');e.status=response.status;throw e}return data;}
 function cache(){if(!user)return;try{localStorage.setItem(cacheKey(user.id),JSON.stringify({state:pending||getState(),revision,dirty}))}catch{status='Browser storage unavailable — export a backup.'}}
 function setStatus(s){status=s;document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=s)}
 async function activate(profile){const token=++generation;resetPrivateUI();user=profile;canSync=false;clearTimeout(timer);let cached;try{cached=JSON.parse(localStorage.getItem(cacheKey(user.id))||'null')}catch{}let next=defaults();try{const cloud=await api('/api/progress');if(token!==generation)return;revision=cloud.revision;next=cloud.state||cached?.state||defaults();dirty=!!cached?.dirty;if(dirty)next=mergeProgress(cloud.state,cached.state);canSync=true;setStatus(dirty?'Local changes waiting to sync':'Cloud progress loaded');}catch(e){revision=cached?.revision||0;next=cached?.state||defaults();dirty=!!cached?.dirty;setStatus('Cloud unavailable — working from this account’s local copy.');error=e.message;}
 if(token!==generation)return;pending=normalizeState(next);onState(pending);cache();if(dirty&&canSync)schedule();onChange();}
 function schedule(){clearTimeout(timer);timer=setTimeout(()=>flush().catch(()=>{}),800)}
 async function flush(){if(!user||!dirty)return;if(flushing)return flushing;const uid=user.id,token=generation;flushing=(async()=>{try{if(!canSync){const cloud=await api('/api/progress');if(token!==generation)return;revision=cloud.revision;pending=mergeProgress(cloud.state,pending||getState());canSync=true;onState(pending,false)}setStatus('Saving to your account…');let snapshot=normalizeState(pending||getState()),at=sequence;let result;try{result=await api('/api/progress',{state:snapshot,revision},'PUT')}catch(e){if(e.status!==409)throw e;const cloud=await api('/api/progress');if(token!==generation)return;revision=cloud.revision;snapshot=mergeProgress(cloud.state,pending||snapshot);at=sequence;result=await api('/api/progress',{state:snapshot,revision},'PUT')}
 if(token!==generation||user?.id!==uid)return;revision=result.revision;if(sequence===at){dirty=false;pending=normalizeState(result.state);onState(pending,false)}setStatus(dirty?'New changes waiting to sync':'Synced to your account');cache();if(dirty)schedule();
 }catch(e){if(token===generation){setStatus(e.status===401?'Session expired — log in to sync.':'Sync paused — local copy saved.');cache();notify(e.message)}throw e}finally{flushing=null}})();return flushing;}
 function save(state){if(!user)return false;pending=normalizeState(state);dirty=true;sequence++;cache();setStatus('Changes saved locally; sync pending');schedule();return true;}
 async function init(){try{const availability=await api('/api/auth/status');configured=availability.configured;if(configured){const session=await api('/api/auth/session');if(session.user)await activate(session.user)}}catch{configured=false}onChange();}
 function recoveryView(mode){const reset=mode==='reset';return `<section class="auth-layout"><aside class="auth-story"><span class="eyebrow">NEXORA ACCOUNT ACCESS</span><h1>${reset?'Choose a new password.':'Let’s get you back to learning.'}</h1><p>${reset?'Use a strong passphrase you have not used elsewhere.':'Request a secure, one-time recovery link. We will not reveal whether an email address has an account.'}</p><button class="btn secondary" data-page="login">Back to Log In</button></aside><section class="auth-card"><h2>${reset?'Reset password':'Password recovery'}</h2>${configured===false?'<div class="auth-config">Account services are not configured. The project owner must set up Supabase.</div>':''}${error?`<div class="auth-error" role="alert">${htmlEscape(error)}</div>`:''}${notice?`<div class="feedback" role="status">${htmlEscape(notice)}</div>`:''}<form id="account-form" data-mode="${mode}">${reset?'<label>New password<div class="password-field"><input id="password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><button type="button" data-show="password">Show</button></div></label><label>Confirm new password<div class="password-field"><input id="confirm-password" name="confirm_password" type="password" autocomplete="new-password" required><button type="button" data-show="confirm-password">Show</button></div></label>':'<label>Email address<input id="email" type="email" name="email" autocomplete="email" required maxlength="254"></label>'}<button class="btn auth-submit" type="submit">${reset?'Save new password':'Send recovery link'}</button></form><p class="micro">Recovery links expire and can be used only once. Never share them.</p></section></section>`;}
 function view(mode){if(['recover','reset'].includes(mode))return recoveryView(mode);const esc=htmlEscape,signup=mode==='signup',profile=mode==='profile';return `<section class="auth-layout"><aside class="auth-story"><span class="eyebrow">YOUR CURIOSITY. YOUR JOURNEY.</span><h1>${profile?'Your learning identity.':signup?'Make your progress yours.':'Welcome back to NEXORA.'}</h1><p>${profile?'Your profile and progress belong to your account.':signup?'Keep your discoveries, achievements, and learning preferences together across devices.':'Pick up where you left off. Your next discovery is waiting.'}</p><div class="auth-benefits"><p>◈ Six subjects, connected</p><p>✦ Four ways to learn</p><p>◇ Your progress, saved</p></div><button class="btn secondary" data-page="home">${profile?'Back to dashboard':'Continue as a guest →'}</button></aside><section class="auth-card"><span class="eyebrow">${profile?'YOUR ACCOUNT':signup?'START YOUR JOURNEY':'YOUR LEARNING SPACE'}</span><h2>${profile?'Profile Settings':signup?'Create an account':'Log in'}</h2>${configured===false?'<div class="auth-config" role="status">Accounts are not configured on this deployment. Guest learning is available. The project owner must configure the included Supabase integration.</div>':''}${error?`<div class="auth-error" role="alert">${esc(error)}</div>`:''}${notice?`<div class="feedback" role="status">${esc(notice)}</div>`:''}${profile&&!user?'<p>Log in to view your profile.</p><button class="btn" data-page="login">Log In</button>':`<form id="account-form" data-mode="${mode}" aria-busy="${busy}">${signup||profile?`<label for="full-name">Full name<input id="full-name" name="full_name" autocomplete="name" required maxlength="100" value="${profile?esc(user.full_name):''}"></label>`:''}${signup?'<label for="username">Username<input id="username" name="username" autocomplete="username" required pattern="[A-Za-z][A-Za-z0-9_]{2,23}" minlength="3" maxlength="24" placeholder="Choose a unique username"><small>3–24 letters, numbers, or underscores. Start with a letter.</small></label><label for="email">Email address<input id="email" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@example.com"></label>':profile?`<p class="muted">Username: @${esc(user.username)}<br><span data-sync-status>${esc(status)}</span></p>`:'<label for="identifier">Email or username<input id="identifier" name="identifier" autocomplete="username" required maxlength="254" placeholder="Email address or username"></label>'}${!profile?`<label for="password">Password<div class="password-field"><input id="password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" ${signup?'minlength="12"':''} maxlength="128" required><button type="button" data-show="password" aria-label="Show password">Show</button></div>${signup?'<small>Use at least 12 characters. A long passphrase works well.</small>':''}</label>${signup?'<label for="confirm-password">Confirm password<div class="password-field"><input id="confirm-password" name="confirm_password" type="password" autocomplete="new-password" required><button type="button" data-show="confirm-password" aria-label="Show confirm password">Show</button></div></label>':''}`:''}<button class="btn auth-submit" type="submit" ${busy?'disabled':''}>${busy?'Please wait…':profile?'Save profile':signup?'Create account →':'Log in →'}</button></form>`}${!profile?`${!signup&&!profile?'<p><button class="link" data-page="recover">Forgot your password?</button></p>':''}<p class="auth-switch">${signup?'Already learning with us?':'New to NEXORA?'} <button class="link" data-page="${signup?'login':'signup'}">${signup?'Log In':'Sign Up'}</button></p><p class="micro">No account is needed to explore. Passwords are handled by Supabase Auth and never saved in your browser.</p>`:`<div class="account-tools"><button class="btn secondary" data-account="sync">Sync now</button><button class="btn secondary" data-account="import-guest">Import guest progress</button><button class="link" data-account="logout">Log Out</button></div><p class="micro">Guest progress is imported only when you choose it. Usernames stay fixed to preserve unique account identity.</p>`}</section></section>`;}
 async function submit(form){if(busy)return;const mode=form.dataset.mode,body=Object.fromEntries(new FormData(form));if(['signup','reset'].includes(mode)&&body.password!==body.confirm_password){error='The passwords do not match.';form.querySelector('#confirm-password').setCustomValidity(error);form.querySelector('#confirm-password').reportValidity();form.querySelector('#confirm-password').addEventListener('input',()=>form.querySelector('#confirm-password').setCustomValidity(''),{once:true});return}busy=true;error='';notice='';const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Please wait…';form.setAttribute('aria-busy','true');try{const result=await api('/api/auth/'+(mode==='profile'?'profile':mode==='reset'?'password':mode),body,mode==='profile'?'PATCH':'POST');if(mode==='reset'&&result.updated){generation++;clearTimeout(timer);resetPrivateUI();user=null;pending=null;dirty=false;revision=0;canSync=false;status='Guest · Saved on this device';onState(readState(localStorage));navigate('login');notice='Password changed. Log in with your new password.';onChange()}else if(result.user){if(mode==='profile'){user=result.user;notice='Profile updated.';onChange()}else{await activate(result.user);navigate('home');notify('Welcome, '+result.user.full_name+'. You are signed in.')}}else{notice=result.message;onChange()}}catch(e){error=e.message;let el=form.parentElement.querySelector('.auth-error');if(!el){el=document.createElement('div');el.className='auth-error';el.setAttribute('role','alert');form.before(el)}el.textContent=error;}finally{busy=false;if(submit.isConnected){submit.disabled=false;submit.textContent=mode==='profile'?'Save profile':mode==='signup'?'Create account →':mode==='recover'?'Send recovery link':mode==='reset'?'Save new password':'Log in →';form.setAttribute('aria-busy','false')}else onChange()}}
 async function action(name){if(name==='sync'){await flush().catch(()=>{});onChange()}if(name==='import-guest'&&user){if(!confirm('Merge this browser’s guest progress into your account? Existing completions will be preserved.'))return;const merged=mergeProgress(getState(),readState(localStorage));onState(merged,false);save(merged);await flush().catch(()=>{});onChange()}if(name==='logout'){if(!user)return;await flush().catch(()=>{});try{await api('/api/auth/logout',{});const uid=user.id;generation++;clearTimeout(timer);resetPrivateUI();if(!dirty)localStorage.removeItem(cacheKey(uid));user=null;pending=null;revision=0;dirty=false;canSync=false;error='';notice='';status='Guest · Saved on this device';onState(readState(localStorage));navigate('home');notify('Logged out. You are now learning as a guest.')}catch(e){notify(e.message)}}}
 document.addEventListener('submit',e=>{if(e.target.id==='account-form'){e.preventDefault();submit(e.target)}});document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.show){const input=document.getElementById(b.dataset.show);input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Show':'Hide';b.setAttribute('aria-label',b.textContent+' password')}if(b.dataset.account)action(b.dataset.account)});window.addEventListener('online',()=>{if(user&&dirty)flush().catch(()=>{})});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&user&&dirty)flush().catch(()=>{})});
 return {get user(){return user},get configured(){return configured},get status(){return status},view,init,save,flush,clearMessages(){error='';notice=''}};
}
